    {"id": "robert-hanssen-spy-2001", "name": "Robert Hanssen (spy)", "type": "Espionage", "status": "Solved", "year": 2001, "date": "February 18, 2001", "state": "Virginia", "city": "Vienna", "age": 56, "gender": "Male", "summary": "FBI agent Robert Hanssen was arrested for spying for Russia for 22 years. He is considered the most damaging spy in FBI history, compromising dozens of agents. He died in prison in 2023.", "lastSeen": "February 18, 2001, Foxstone Park, Vienna, Virginia", "tags": ["espionage", "Virginia", "2000s", "solved"], "sources": [{"title": "Robert Hanssen - Wikipedia", "url": "https://en.wikipedia.org/wiki/Robert_Hanssen"}, {"title": "Hanssen case - FBI", "url": "https://www.fbi.gov/history/famous-cases/robert-hanssen"}, {"title": "Hanssen death - CNN", "url": "https://www.cnn.com/2023/06/05/politics/robert-hanssen-dies/index.html"}], "narrative": ["On February 18, 2001, FBI agent Robert Hanssen was arrested at Foxstone Park in Vienna, Virginia while making a dead drop for Russian intelligence. He had been spying for the Soviet Union and Russia for 22 years.", "Hanssen compromised dozens of intelligence operations, revealed the identities of three KGB agents working for the U.S. (two of whom were executed), and provided thousands of classified documents.", "His espionage was particularly devastating because he held senior counterintelligence positions—he was literally the person tasked with catching spies like himself.", "Hanssen pleaded guilty to 15 counts of espionage and was sentenced to 15 consecutive life sentences. He died in federal prison on June 5, 2023. His story was depicted in the film 'Breach.'"], "timeline": [{"date": "2001-02-18", "event": "Hanssen arrested at dead drop."}, {"date": "2002-05-10", "event": "Sentenced to 15 consecutive life terms."}, {"date": "2023-06-05", "event": "Dies in prison."}], "enriched": True},
    {"id": "aldrich-ames-cia-1994", "name": "Aldrich Ames (spy)", "type": "Espionage", "status": "Solved", "year": 1994, "date": "February 21, 1994", "state": "Virginia", "city": "Arlington", "age": 52, "gender": "Male", "summary": "CIA officer Aldrich Ames spied for the Soviet Union for nine years, compromising more than 100 intelligence operations. At least 10 agents he betrayed were executed. He is serving life in prison.", "lastSeen": "February 21, 1994, his home in Arlington, Virginia", "tags": ["espionage", "Virginia", "1990s", "solved"], "sources": [{"title": "Aldrich Ames - Wikipedia", "url": "https://en.wikipedia.org/wiki/Aldrich_Ames"}, {"title": "Ames case - CIA", "url": "https://www.cia.gov/stories/story/aldrich-ames/"}, {"title": "Ames arrest - New York Times", "url": "https://www.nytimes.com/1994/02/22/us/cia-officer-charged-as-spy.html"}], "narrative": ["On February 21, 1994, CIA counterintelligence officer Aldrich Ames was arrested at his home in Arlington, Virginia for spying for the Soviet Union and Russia since 1985.", "Ames had been paid $2.7 million by the KGB, making him the highest-paid spy in history at the time. He used the money to buy a $540,000 house and a Jaguar—purchases that should have raised red flags.", "His betrayals led to the exposure and execution of at least 10 CIA sources within the Soviet Union, including Dmitri Polyakov, considered one of the most valuable U.S. intelligence assets of the Cold War.", "Ames pleaded guilty and was sentenced to life without parole. His case, along with Robert Hanssen's, led to major reforms in how intelligence agencies monitor their own personnel."], "timeline": [{"date": "1994-02-21", "event": "Ames arrested."}, {"date": "1994-04-28", "event": "Sentenced to life without parole."}], "enriched": True},
    {"id": "whitey-bulger-2018", "name": "Whitey Bulger (death)", "type": "Homicide", "status": "Solved", "year": 2018, "date": "October 30, 2018", "state": "West Virginia", "city": "Hazelton", "age": 89, "gender": "Male", "summary": "Notorious Boston mob boss Whitey Bulger was beaten to death hours after arriving at a West Virginia federal prison. Fotios 'Freddy' Geas was charged. Bulger had been an FBI informant for decades.", "lastSeen": "October 30, 2018, USP Hazelton, Bruceton Mills, West Virginia", "tags": ["homicide", "West Virginia", "2010s", "organized crime", "solved"], "sources": [{"title": "James 'Whitey' Bulger death - Wikipedia", "url": "https://en.wikipedia.org/wiki/Whitey_Bulger#Death"}, {"title": "Bulger killed - Boston Globe", "url": "https://www.bostonglobe.com/metro/whitey-bulger-killed/"}, {"title": "Geas charged - CNN", "url": "https://www.cnn.com/2018/10/30/us/whitey-bulger-killed/index.html"}], "narrative": ["On October 30, 2018, James 'Whitey' Bulger, 89, was beaten to death at USP Hazelton in West Virginia. He had arrived at the prison just hours before, after being transferred from a facility in Florida.", "Bulger, the notorious Boston crime boss who was also a longtime FBI informant, was found in his cell. He had been beaten with a lock stuffed in a sock and his eyes had been reportedly disfigured.", "Fotios 'Freddy' Geas, a Mafia hitman, was charged with the murder. Geas reportedly despised informants. Questions arose about why the 89-year-old Bulger was transferred to a high-security facility.", "Bulger had been on the FBI's Most Wanted list for 16 years before being captured in Santa Monica, California in 2011. His story was depicted in the film 'Black Mass' starring Johnny Depp."], "timeline": [{"date": "2011-06-22", "event": "Bulger captured in Santa Monica."}, {"date": "2013-08-12", "event": "Convicted of 11 murders."}, {"date": "2018-10-30", "event": "Beaten to death in prison."}], "enriched": True},
    {"id": "jesse-matthews-hannah-graham", "name": "Hannah Graham", "type": "Homicide", "status": "Solved", "year": 2014, "date": "September 13, 2014", "state": "Virginia", "city": "Charlottesville", "age": 18, "gender": "Female", "summary": "University of Virginia student Hannah Graham vanished after a night out. Jesse Matthew was convicted of her murder and linked to several other attacks through DNA, including Morgan Harrington's murder.", "lastSeen": "September 13, 2014, Charlottesville, Virginia", "tags": ["homicide", "Virginia", "2010s", "solved"], "sources": [{"title": "Murder of Hannah Graham - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Hannah_Graham"}, {"title": "Graham case - Daily Progress", "url": "https://www.dailyprogress.com/news/crime/hannah-graham/"}, {"title": "Matthew conviction - CNN", "url": "https://www.cnn.com/2016/03/02/us/hannah-graham-case/index.html"}], "narrative": ["On September 13, 2014, University of Virginia sophomore Hannah Graham, 18, disappeared after a night out in Charlottesville. Surveillance footage showed her walking with a man later identified as Jesse Matthew.", "Hannah's remains were found five weeks later in rural Albemarle County. Jesse Matthew, a hospital worker, was arrested in Texas after fleeing Virginia.", "DNA evidence linked Matthew not only to Graham's murder but also to the 2009 murder of Virginia Tech student Morgan Harrington and a 2005 sexual assault in Fairfax County.", "Matthew pleaded guilty to both the Graham and Harrington murders and was sentenced to four consecutive life terms."], "timeline": [{"date": "2014-09-13", "event": "Hannah Graham disappears."}, {"date": "2016-03-02", "event": "Matthew sentenced to four life terms."}], "enriched": True},
    {"id": "joseph-deangelo-east-area-rapist", "name": "East Area Rapist Victims", "type": "Serial Rape", "status": "Solved", "year": 1976, "date": "1976-1979", "state": "California", "city": "Sacramento", "age": None, "gender": "Female", "summary": "Before becoming the Golden State Killer, Joseph James DeAngelo committed at least 50 rapes in the Sacramento area as the East Area Rapist. He terrorized neighborhoods from 1976 to 1979.", "lastSeen": "1976-1979, Sacramento area, California", "tags": ["serial rape", "California", "1970s", "solved"], "sources": [{"title": "East Area Rapist - Wikipedia", "url": "https://en.wikipedia.org/wiki/Golden_State_Killer#East_Area_Rapist"}, {"title": "EAR case files - Sacramento Bee", "url": "https://www.sacbee.com/news/local/crime/east-area-rapist/"}, {"title": "I'll Be Gone in the Dark - HBO", "url": "https://www.hbo.com/ill-be-gone-in-the-dark"}], "narrative": ["Between 1976 and 1979, a masked intruder terrorized the Sacramento area, breaking into homes and raping women while their partners were tied up in adjacent rooms. He was known as the East Area Rapist.", "The attacker committed at least 50 sexual assaults with a distinctive MO: he would stake out neighborhoods, sometimes calling victims beforehand, and would stack dishes on the bound partner's back to alert him if they moved.", "The East Area Rapist was later linked through DNA to the Original Night Stalker murders in Southern California, and both were linked to the Visalia Ransacker burglaries—all committed by the same person.", "The case was finally solved in 2018 when genetic genealogy identified Joseph James DeAngelo, a former police officer, as the perpetrator. Michelle McNamara's book 'I'll Be Gone in the Dark' helped revive public interest."], "timeline": [{"date": "1976-06-18", "event": "First known East Area Rapist attack."}, {"date": "2018-04-24", "event": "DeAngelo arrested through genetic genealogy."}], "enriched": True},
    {"id": "pamela-smart-1990", "name": "Pamela Smart (case)", "type": "Homicide", "status": "Solved", "year": 1990, "date": "May 1, 1990", "state": "New Hampshire", "city": "Derry", "age": 22, "gender": "Female", "summary": "Pamela Smart manipulated her 15-year-old student lover into murdering her husband Gregg. She was convicted of conspiracy to commit murder and sentenced to life without parole.", "lastSeen": "May 1, 1990, Smart home, Derry, Rockingham County, New Hampshire", "tags": ["homicide", "New Hampshire", "1990s", "solved"], "sources": [{"title": "Pamela Smart - Wikipedia", "url": "https://en.wikipedia.org/wiki/Pamela_Smart"}, {"title": "Smart case - Concord Monitor", "url": "https://www.concordmonitor.com/pamela-smart/"}, {"title": "To Die For film - IMDB", "url": "https://www.imdb.com/title/tt0114681/"}], "narrative": ["On May 1, 1990, Gregg Smart, 24, was found shot dead in the couple's condominium in Derry, New Hampshire. It appeared to be a burglary gone wrong.", "Investigation revealed that Gregg's wife Pamela, a 22-year-old high school media coordinator, had seduced her 15-year-old student Billy Flynn and manipulated him and two friends into killing Gregg.", "The trial was one of the first to be televised nationally, prefiguring the O.J. Simpson trial. It became a media sensation.", "Pamela Smart was convicted of conspiracy to commit murder and sentenced to life without parole. The teenagers received lesser sentences and have all been released. Smart's case inspired the Nicole Kidman film 'To Die For.'"], "timeline": [{"date": "1990-05-01", "event": "Gregg Smart murdered."}, {"date": "1991-03-22", "event": "Pamela Smart convicted; sentenced to life."}], "enriched": True},
    {"id": "richard-glossip-oklahoma", "name": "Richard Glossip (case)", "type": "Death Row", "status": "Unsolved", "year": 2025, "date": "2025", "state": "Oklahoma", "city": "Oklahoma City", "age": 61, "gender": "Male", "summary": "Richard Glossip has been on Oklahoma's death row since 1997 for the murder of Barry Van Treese. Even the state's attorney general has questioned his conviction. The Supreme Court heard his case in 2024.", "lastSeen": "1997-present, Oklahoma State Penitentiary", "tags": ["death row", "Oklahoma", "2020s", "unsolved"], "sources": [{"title": "Richard Glossip - Wikipedia", "url": "https://en.wikipedia.org/wiki/Richard_Glossip"}, {"title": "Glossip Supreme Court - SCOTUSblog", "url": "https://www.scotusblog.com/case-files/cases/glossip-v-oklahoma/"}, {"title": "Glossip innocence - The Intercept", "url": "https://theintercept.com/richard-glossip/"}], "narrative": ["Richard Glossip was convicted of the 1997 murder of his boss Barry Van Treese at the Best Budget Inn in Oklahoma City. The actual killer, Justin Sneed, received life in prison in exchange for testifying that Glossip hired him.", "Glossip has maintained his innocence for over 25 years. No physical evidence links him to the crime—the entire case rests on Sneed's testimony.", "In an extraordinary move, Oklahoma's own attorney general concluded that the conviction was unreliable, citing destroyed evidence and Sneed's undisclosed psychiatric history.", "The U.S. Supreme Court heard the case in 2024, marking a rare instance where a state's attorney general argued alongside a death row inmate that the conviction should be overturned."], "timeline": [{"date": "1997-01-07", "event": "Barry Van Treese murdered."}, {"date": "2024-10-09", "event": "Supreme Court hears Glossip v. Oklahoma."}], "enriched": True},
    {"id": "robert-blake-2005", "name": "Bonny Lee Bakley (Robert Blake)", "type": "Homicide", "status": "Unsolved", "year": 2001, "date": "May 4, 2001", "state": "California", "city": "Studio City", "age": 44, "gender": "Female", "summary": "Actor Robert Blake's wife Bonny Lee Bakley was shot dead outside a restaurant. Blake was acquitted of murder but found liable in a civil trial. The case officially remains unsolved.", "lastSeen": "May 4, 2001, Vitello's restaurant, Studio City, Los Angeles, California", "tags": ["homicide", "California", "2000s", "unsolved"], "sources": [{"title": "Bonny Lee Bakley - Wikipedia", "url": "https://en.wikipedia.org/wiki/Bonny_Lee_Bakley"}, {"title": "Blake trial - Los Angeles Times", "url": "https://www.latimes.com/entertainment/robert-blake/"}, {"title": "Blake acquittal - CNN", "url": "https://www.cnn.com/2005/LAW/03/16/blake.trial/index.html"}], "narrative": ["On May 4, 2001, Bonny Lee Bakley was shot and killed while sitting in a car outside Vitello's restaurant in Studio City, Los Angeles. Her husband, actor Robert Blake, said he had returned to the restaurant to retrieve a gun he'd left behind.", "Blake was arrested and charged with murder. His trial drew comparisons to the O.J. Simpson case—another celebrity accused of killing a spouse.", "Blake was acquitted of murder in 2005 but found liable for Bakley's death in a civil suit and ordered to pay $15 million. He was unable to pay.", "Blake died on March 9, 2023 at age 89. The murder of Bonny Lee Bakley officially remains unsolved."], "timeline": [{"date": "2001-05-04", "event": "Bonny Lee Bakley shot dead."}, {"date": "2005-03-16", "event": "Robert Blake acquitted of murder."}], "enriched": True},
    {"id": "natalia-grace-barnett-2019", "name": "Natalia Grace Barnett", "type": "Abandonment/Fraud", "status": "Solved", "year": 2023, "date": "September 2023", "state": "Indiana", "city": "Lafayette", "age": None, "gender": "Female", "summary": "Michael and Kristine Barnett adopted Natalia Grace, a Ukrainian-born woman with dwarfism, then had her age legally changed from 8 to 22 and abandoned her. Michael was convicted of neglect.", "lastSeen": "2013-present, various locations, Indiana", "tags": ["abandonment", "Indiana", "2020s", "solved"], "sources": [{"title": "Natalia Grace Barnett - Wikipedia", "url": "https://en.wikipedia.org/wiki/Natalia_Grace_Barnett"}, {"title": "Curious Case of Natalia Grace - ID Channel", "url": "https://www.investigationdiscovery.com/show/the-curious-case-of-natalia-grace"}, {"title": "Barnett trial - Indianapolis Star", "url": "https://www.indystar.com/story/news/crime/natalia-barnett/"}], "narrative": ["In 2010, Michael and Kristine Barnett adopted Natalia Grace, described as a 6-year-old Ukrainian orphan with a form of dwarfism called spondyloepiphyseal dysplasia.", "In 2012, the Barnetts petitioned a court to change Natalia's age from 8 to 22, claiming she was actually an adult posing as a child. They then moved to Canada and left Natalia in a Lafayette, Indiana apartment.", "The case became a media sensation, with debate over whether Natalia was a child who had been abandoned or an adult who had deceived her adoptive family. Medical experts disagreed on her actual age.", "Michael Barnett was convicted of neglecting a dependent in 2022. Charges against Kristine were dropped. Natalia was later taken in by another family and has maintained she was always a child."], "timeline": [{"date": "2012-07-01", "event": "Barnetts petition to change Natalia's age."}, {"date": "2022-09-12", "event": "Michael Barnett convicted of neglect."}], "enriched": True},
    {"id": "rust-shooting-baldwin-2024", "name": "Halyna Hutchins (Rust trial)", "type": "Involuntary Manslaughter", "status": "Solved", "year": 2024, "date": "July 12, 2024", "state": "New Mexico", "city": "Santa Fe", "age": 42, "gender": "Female", "summary": "Involuntary manslaughter charges against Alec Baldwin for the death of Halyna Hutchins on the Rust set were dismissed after the judge ruled prosecutors withheld evidence from the defense.", "lastSeen": "October 21, 2021, Bonanza Creek Ranch, Santa Fe, New Mexico", "tags": ["involuntary manslaughter", "New Mexico", "2020s", "solved"], "sources": [{"title": "Rust shooting trial - Wikipedia", "url": "https://en.wikipedia.org/wiki/Rust_(film)#Trial"}, {"title": "Baldwin charges dismissed - CNN", "url": "https://www.cnn.com/2024/07/12/entertainment/alec-baldwin-rust-trial/index.html"}, {"title": "Hutchins death - New York Times", "url": "https://www.nytimes.com/2024/07/12/arts/alec-baldwin-rust-trial-dismissed.html"}], "narrative": ["On October 21, 2021, cinematographer Halyna Hutchins was killed on the set of the film 'Rust' in Santa Fe, New Mexico when a prop gun held by actor Alec Baldwin discharged a live round.", "Armorer Hannah Gutierrez-Reed was convicted of involuntary manslaughter in March 2024 for allowing live ammunition onto the set. She was sentenced to 18 months in prison.", "Baldwin was charged with involuntary manslaughter but his trial was dramatically dismissed in July 2024 after Judge Mary Marlowe Sommer ruled that prosecutors had withheld ballistics evidence from the defense.", "The case raised nationwide questions about firearms safety protocols on film sets and led to significant changes in industry practices."], "timeline": [{"date": "2021-10-21", "event": "Halyna Hutchins killed on Rust set."}, {"date": "2024-03-06", "event": "Armorer Gutierrez-Reed convicted."}, {"date": "2024-07-12", "event": "Charges against Baldwin dismissed."}], "enriched": True},
    {"id": "barry-morphew-arrest-2021", "name": "Barry Morphew (arrest detail)", "type": "Homicide", "status": "Unsolved", "year": 2021, "date": "May 5, 2021", "state": "Colorado", "city": "Poncha Springs", "age": 53, "gender": "Male", "summary": "Barry Morphew was arrested for the murder of his wife Suzanne in 2021. He also illegally cast her ballot for Trump. Murder charges were dropped in 2022 but he was convicted of the ballot fraud.", "lastSeen": "May 5, 2021, Poncha Springs, Chaffee County, Colorado", "tags": ["homicide", "Colorado", "2020s", "unsolved"], "sources": [{"title": "Barry Morphew arrest - Denver Post", "url": "https://www.denverpost.com/tag/barry-morphew/"}, {"title": "Ballot fraud - Colorado Sun", "url": "https://coloradosun.com/barry-morphew-ballot/"}, {"title": "Charges dropped - CNN", "url": "https://www.cnn.com/2022/04/19/us/barry-morphew-charges-dropped/index.html"}], "narrative": ["Barry Morphew was arrested on May 5, 2021 and charged with first-degree murder in the disappearance of his wife Suzanne, who vanished on Mother's Day 2020.", "During the investigation, authorities discovered that Barry had submitted his missing wife's mail-in ballot for Donald Trump in the 2020 presidential election, claiming she would have wanted him to.", "Murder charges were dropped in April 2022 before trial, with prosecutors citing evidence concerns. Barry was convicted of forgery for casting Suzanne's ballot.", "Suzanne's remains were found in September 2023. As of 2024, Barry Morphew has not been recharged with murder."], "timeline": [{"date": "2021-05-05", "event": "Barry Morphew arrested for murder."}, {"date": "2022-04-19", "event": "Murder charges dropped."}], "enriched": True},
    {"id": "elizabeth-holmes-theranos-2022", "name": "Elizabeth Holmes (Theranos)", "type": "Fraud", "status": "Solved", "year": 2022, "date": "January 3, 2022", "state": "California", "city": "San Jose", "age": 37, "gender": "Female", "summary": "Theranos founder Elizabeth Holmes was convicted of fraud for deceiving investors about her blood-testing technology. She was sentenced to over 11 years in federal prison.", "lastSeen": "January 3, 2022, U.S. District Court, San Jose, California", "tags": ["fraud", "California", "2020s", "solved"], "sources": [{"title": "Elizabeth Holmes - Wikipedia", "url": "https://en.wikipedia.org/wiki/Elizabeth_Holmes"}, {"title": "Holmes verdict - Wall Street Journal", "url": "https://www.wsj.com/articles/elizabeth-holmes-theranos-verdict/"}, {"title": "Holmes sentencing - CNN", "url": "https://www.cnn.com/2022/11/18/tech/elizabeth-holmes-sentencing/index.html"}], "narrative": ["On January 3, 2022, Elizabeth Holmes, the former CEO of blood-testing startup Theranos, was found guilty of four counts of wire fraud and conspiracy to commit fraud against investors.", "Holmes had claimed her company's technology could run hundreds of medical tests from a single drop of blood. In reality, the technology didn't work, and Theranos secretly ran most tests on conventional machines.", "At its peak, Theranos was valued at $9 billion. Holmes was celebrated as a visionary—the youngest female self-made billionaire. Her board included Henry Kissinger and George Shultz.", "Holmes was sentenced to 11 years and 3 months in federal prison. She reported to prison in May 2023. The case became a defining cautionary tale of Silicon Valley hubris."], "timeline": [{"date": "2022-01-03", "event": "Holmes convicted of fraud."}, {"date": "2023-05-30", "event": "Holmes reports to federal prison."}], "enriched": True},
    {"id": "anna-delvey-sorokin-2019", "name": "Anna Delvey (Sorokin)", "type": "Fraud", "status": "Solved", "year": 2019, "date": "May 9, 2019", "state": "New York", "city": "New York City", "age": 28, "gender": "Female", "summary": "Anna Sorokin, posing as German heiress 'Anna Delvey,' defrauded New York banks, hotels, and acquaintances of hundreds of thousands of dollars. She was convicted of theft and grand larceny.", "lastSeen": "Various dates, Manhattan, New York", "tags": ["fraud", "New York", "2010s", "solved"], "sources": [{"title": "Anna Sorokin - Wikipedia", "url": "https://en.wikipedia.org/wiki/Anna_Sorokin"}, {"title": "Anna Delvey - New York Magazine", "url": "https://www.thecut.com/article/how-anna-delvey-tricked-new-york.html"}, {"title": "Sorokin trial - CNN", "url": "https://www.cnn.com/2019/04/25/us/anna-sorokin-delvey-trial/index.html"}], "narrative": ["Anna Sorokin, a Russian-born German national, posed as 'Anna Delvey,' a wealthy German heiress, and infiltrated New York's social scene between 2013 and 2017.", "She defrauded banks, hotels, and individuals, attempting to secure a $22 million loan for a private arts club. She lived in luxury hotels without paying, stiffed friends with expenses, and forged bank statements.", "Sorokin was convicted of theft of services, grand larceny, and other charges in May 2019. She was sentenced to 4 to 12 years in prison.", "Her story was adapted into Netflix's 'Inventing Anna.' Sorokin was released in 2021 but remained in ICE custody due to her overstayed visa. She was released on house arrest and launched a podcast."], "timeline": [{"date": "2017-10-03", "event": "Sorokin arrested."}, {"date": "2019-05-09", "event": "Convicted of fraud; sentenced to 4-12 years."}], "enriched": True},
